//! One-use, exact-batch confirmation tickets for in-page permanent deletion.
use std::{collections::HashMap,sync::{Mutex,OnceLock},time::{Duration,Instant},io::Read};
struct Ticket{ids:Vec<String>,at:Instant}
fn tickets()->&'static Mutex<HashMap<String,Ticket>>{static T:OnceLock<Mutex<HashMap<String,Ticket>>>=OnceLock::new();T.get_or_init(Default::default)}
pub fn issue(ids:&[String])->Result<String,String>{let mut sorted=ids.to_vec();sorted.sort();sorted.dedup();if sorted.is_empty()||sorted.len()!=ids.len(){return Err("确认批次无效".into())}let mut bytes=[0u8;24];std::fs::File::open("/dev/urandom").and_then(|mut f|f.read_exact(&mut bytes)).map_err(|_|"无法准备确认")?;let id=bytes.iter().map(|b|format!("{b:02x}")).collect::<String>();let mut t=tickets().lock().map_err(|_|"确认暂不可用")?;t.retain(|_,v|v.at.elapsed()<Duration::from_secs(300));t.insert(id.clone(),Ticket{ids:sorted,at:Instant::now()});Ok(id)}
pub fn consume(id:&str,ids:&[String])->Result<(),String>{let t=tickets().lock().map_err(|_|"确认暂不可用")?.remove(id).ok_or("确认已失效，请重新确认")?;let mut sorted=ids.to_vec();sorted.sort();if t.at.elapsed()>Duration::from_secs(300)||t.ids!=sorted{return Err("确认范围已变化，请重新确认".into())}Ok(())}
#[cfg(test)]mod tests{use super::*;#[test]fn exact_batch_only_and_one_use(){let ids=vec!["owned-a".into(),"owned-b".into()];let token=issue(&ids).unwrap();assert!(consume(&token,&["owned-a".into()]).is_err());assert!(consume(&token,&ids).is_err());let token=issue(&ids).unwrap();assert!(consume(&token,&ids).is_ok());assert!(consume(&token,&ids).is_err());}#[test]fn duplicates_rejected(){assert!(issue(&["a".into(),"a".into()]).is_err())}}
